class Payment {
  process(): boolean {
    return true;
  }
  retailSurcharge(amount: number): number {
    // retail specific calculation
    return amount * 0.05;
  }
}

class RetailPayment extends Payment {
  finalAmount(amount: number): number {
    return amount + this.retailSurcharge(amount);
  }
}

class CorporatePayment extends Payment {
  finalAmount(amount: number): number {
    return amount;
  }
}

class Document {
  generate(): string { return ''; }
  formatForPrint(): string {
    // formatting used by Report and Invoice only
    return 'formatted';
  }
}

class Report extends Document {
  print(): void { console.log(this.formatForPrint()); }
}

class Invoice extends Document {
  emailCopy(): void { console.log(this.formatForPrint()); }
}

class Memo extends Document {
  archive(): void {}
}

// Version A
class Notification {
  formatForEmail(content: string): string {
    return `<p>${content}</p>`; // email formatting in superclass
  }
}
class EmailNotification extends Notification {
  deliver(content: string) { const body = this.formatForEmail(content); }
}
class SMSNotification extends Notification {
  deliver(content: string) { /* SMS no email formatting */ }
}

// Version B
class NotificationV2 {}
class EmailNotificationV2 extends NotificationV2 {
  private formatForEmail(content: string): string { return `<p>${content}</p>`; }
  deliver(content: string) { const body = this.formatForEmail(content); }
}
class SMSNotificationV2 extends NotificationV2 {
  deliver(content: string) { /* SMS no email formatting */ }
}
